  if (!ok) {
    failures++;
    if (!result.ok) console.log('  illegal step', result.index, result.step, 'action', result.action);
    console.log('  playerLP', state.player.lp, 'enemyLP', state.enemy.lp);
    console.log('  log tail:', state.log.slice(-8).map(l => l.text).join(' / '));
  }
