function stateKey(state) {
  if (!state) return '';
  const strip = card => {
    if (!card) return '-';
    return [
      card.id,
      card.pos,
      card.faceDown ? 1 : 0,
      card.flipTriggered ? 1 : 0,
      card.attacksUsed,
      card.attacksAllowed,
      card.atkBonus,
      card.grantedDirect ? 1 : 0,
      card.effectUsed ? 1 : 0,
      card.changedPosition ? 1 : 0,
      card.setTurn
    ].join(',');
  };
  const side = s => [
    s.lp,
    s.normalUsed ? 1 : 0,
    s.flipUsed ? 1 : 0,
    s.hand.map(c => c.id).join('.'), // hand order affects indexes
