const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => { errors.push('PAGEERROR ' + e.message); });
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });

  for (let stage = 0; stage < 8; stage++) {
    await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
    // Intro may be open; close it.
    if (await page.locator('#introStart').count()) {
      await page.locator('#introStart').click();
      await page.waitForTimeout(250);
    }
    await page.locator('#stageBtn').click();
    await page.waitForTimeout(200);
    const cards = await page.locator('.stage-card').count();
    await page.locator(`.stage-card[data-stage="${stage}"]`).click();
    await page.waitForTimeout(200);
    if (await page.locator('#introStart').count()) {
      await page.locator('#introStart').click();
      await page.waitForTimeout(250);
    }
    const title = await page.locator('#missionName').innerText();
    const par = await page.locator('#missionPar').innerText();
    const boardCards = await page.locator('.zone .card').count();
    const setCards = await page.locator('.zone .card.is-set').count();
    await page.locator('#solutionBtn').click();
    await page.waitForTimeout(200);
    const replay = page.locator('#replaySolution');
    const replayEnabled = await replay.isEnabled();
    if (!replayEnabled) { console.log(`STAGE ${stage + 1} ${title}: replay disabled FAIL`); continue; }
    await replay.click();
    await page.locator('.result').waitFor({ timeout: 30000 });
    await page.waitForTimeout(300);
    const resultText = (await page.locator('.result').innerText()).replace(/\s+/g, ' ').slice(0, 120);
    const win = await page.locator('.result__big').innerText();
    console.log(`STAGE ${stage + 1} ${title} par=${par} stageCards=${cards} board=${boardCards} set=${setCards} result="${win}" text="${resultText}"`);
    await page.screenshot({ path: `/tmp/opencode/e2e-stage${stage + 1}.png` });
  }

  console.log('ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})();

