const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const wait = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });

  async function loadStage(i) {
    await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
    if (await page.locator('#introStart').count()) { await page.locator('#introStart').click(); await wait(250); }
    await page.locator('#stageBtn').click();
    await wait(180);
    await page.locator(`.stage-card[data-stage="${i}"]`).click();
    await wait(180);
    if (await page.locator('#introStart').count()) { await page.locator('#introStart').click(); await wait(300); }
  }
  async function pickHand(name) {
    await page.locator('.hand .card', { hasText: name }).first().click();
    await wait(120);
  }
  async function tray(text) {
    await page.locator('#trayButtons button', { hasText: text }).first().click();
    await wait(150);
  }
  async function zone(side, kind, index) {
    await page.locator(`.zone[data-side="${side}"][data-kind="${kind}"][data-index="${index}"]`).click();
    await wait(150);
  }
  const logText = async () => (await page.locator('#log').innerText()).replace(/\s+/g, ' ');

  // ---------- STAGE 5: set monster -> enemy attacks -> flip -> change position -> attack ----------
  await loadStage(4);
  console.log('S5 start hand', await page.locator('.hand .card').count(), 'enemyLP', await page.locator('#enemyLp').innerText());
  await pickHand('火花のインプ');
  await tray('裏側セット');
  await zone('player', 'monster', 2);
  let setCount = await page.locator('.zone[data-side="player"] .card.is-set').count();
  console.log('S5 after set: player set cards =', setCount, 'actions', await page.locator('#actionNo').innerText());
  await page.screenshot({ path: '/tmp/opencode/manual-s5-set.png' });

  await page.locator('#endTurnBtn').click();
  await page.waitForFunction(() => document.querySelector('#phaseLabel').textContent === 'YOUR TURN', { timeout: 10000 });
  await wait(400);
  const s5log = await logText();
  console.log('S5 after enemy turn: round', await page.locator('#roundNo').innerText(), 'enemyLP', await page.locator('#enemyLp').innerText());
  console.log('S5 log has reverse:', /リバース|反転|1500/.test(s5log), '| snippet:', s5log.slice(-260));
  console.log('S5 flipped card faceup:', await page.locator('.zone[data-side="player"][data-kind="monster"][data-index="2"] .card:not(.is-set)').count());
  await page.screenshot({ path: '/tmp/opencode/manual-s5-flipped.png' });

  await zone('player', 'monster', 2);
  await tray('表示変更');
  await zone('player', 'monster', 2);
  await tray('攻撃');
  await tray('直接攻撃');
  await wait(300);
  await pickHand('火球');
  await tray('発動');
  await wait(300);
  await pickHand('隕石');
  await tray('発動');
  await page.locator('.result').waitFor({ timeout: 15000 });
  await wait(300);
  console.log('S5 RESULT:', (await page.locator('.result').innerText()).replace(/\s+/g, ' ').slice(0, 140));
  await page.screenshot({ path: '/tmp/opencode/manual-s5-result.png' });

  // ---------- STAGE 6: set trap -> enemy direct attack -> reflect auto trigger -> fireball ----------
  await loadStage(5);
  console.log('S6 start enemyLP', await page.locator('#enemyLp').innerText(), 'playerLP', await page.locator('#playerLp').innerText());
  await pickHand('反射の陣');
  await tray('裏側セット');
  await zone('player', 'spell', 0);
  console.log('S6 trap set:', await page.locator('.zone[data-side="player"][data-kind="spell"][data-index="0"] .card.is-set').count());
  await page.screenshot({ path: '/tmp/opencode/manual-s6-trap.png' });

  await page.locator('#endTurnBtn').click();
  await page.waitForFunction(() => document.querySelector('#phaseLabel').textContent === 'YOUR TURN', { timeout: 10000 });
  await wait(400);
  const s6log = await logText();
  console.log('S6 after enemy attack: enemyLP', await page.locator('#enemyLp').innerText(), 'playerLP', await page.locator('#playerLp').innerText());
  console.log('S6 log has reflect:', /反射|返/.test(s6log), '| snippet:', s6log.slice(-300));
  await page.screenshot({ path: '/tmp/opencode/manual-s6-reflect.png' });

  await pickHand('火球');
  await tray('発動');
  await page.locator('.result').waitFor({ timeout: 15000 });
  await wait(300);
  console.log('S6 RESULT:', (await page.locator('.result').innerText()).replace(/\s+/g, ' ').slice(0, 140));
  await page.screenshot({ path: '/tmp/opencode/manual-s6-result.png' });

  console.log('ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})();

