const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const wait = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ headless: true });
  const errors = [];
  async function snap(name, viewport, stage) {
    const page = await browser.newPage({ viewport, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
    page.on('pageerror', e => errors.push(name + ' PAGEERROR ' + e.message));
    page.on('console', m => { if (m.type() === 'error') errors.push(name + ' CONSOLE ' + m.text()); });
    await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
    if (await page.locator('#introStart').count()) { await page.locator('#introStart').click(); await wait(300); }
    await page.locator('#stageBtn').click(); await wait(300);
    await page.screenshot({ path: `/tmp/opencode/m-${name}-select.png` });
    await page.locator(`.stage-card[data-stage="${stage}"]`).click(); await wait(300);
    if (await page.locator('#introStart').count()) { await page.locator('#introStart').click(); await wait(400); }
    await wait(900);
    const overflow = await page.evaluate(() => ({
      doc: document.documentElement.scrollWidth,
      win: innerWidth,
      body: document.body.scrollWidth
    }));
    const cards = await page.locator('.zone .card').count();
    const sets = await page.locator('.zone .card.is-set').count();
    const hand = await page.locator('.hand .card').count();
    console.log(name, viewport, { overflow, cards, sets, hand });
    await page.screenshot({ path: `/tmp/opencode/m-${name}-stage${stage + 1}.png`, fullPage: true });
    await page.locator('.hand .card').first().click(); await wait(300);
    const tray = (await page.locator('#tray').innerText()).replace(/\s+/g, ' ');
    console.log(name, 'tray after select:', tray.slice(0, 140));
    await page.screenshot({ path: `/tmp/opencode/m-${name}-selected.png`, fullPage: true });
    await page.close();
  }
  await snap('390', { width: 390, height: 844 }, 7);
  await snap('360', { width: 360, height: 740 }, 7);
  await snap('land', { width: 844, height: 390 }, 7);
  console.log('ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})();

