const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const wait = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ headless: true });
  const errors = [];
  for (const [name, vp, mobile] of [
    ['320', { width: 320, height: 568 }, true],
    ['1024', { width: 1024, height: 768 }, false]
  ]) {
    const page = await browser.newPage({ viewport: vp, isMobile: mobile, hasTouch: mobile, deviceScaleFactor: mobile ? 2 : 1 });
    page.on('pageerror', e => errors.push(name + ' PAGEERROR ' + e.message));
    page.on('console', m => { if (m.type() === 'error') errors.push(name + ' CONSOLE ' + m.text()); });
    await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
    if (await page.locator('#introStart').count()) { await page.locator('#introStart').click(); await wait(300); }
    await page.locator('#stageBtn').click(); await wait(200);
    await page.locator('.stage-card[data-stage="7"]').click(); await wait(200);
    if (await page.locator('#introStart').count()) { await page.locator('#introStart').click(); await wait(300); }
    await wait(700);
    const m = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, w: innerWidth, sh: document.documentElement.scrollHeight, h: innerHeight }));
    console.log(name, m);
    await page.screenshot({ path: `/tmp/opencode/view-${name}.png`, fullPage: true });
    await page.close();
  }
  console.log('ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})();

