const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const wait = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  if (await page.locator('#introStart').count()) { await page.locator('#introStart').click(); await wait(250); }
  await page.locator('.hand .card', { hasText: '火球' }).first().click(); await wait(150);
  await page.locator('#trayButtons button', { hasText: 'セット' }).first().click(); await wait(150);
  await page.locator('.zone[data-side="player"][data-kind="spell"][data-index="0"]').click(); await wait(500);
  console.log('set spell count', await page.locator('.zone[data-side="player"][data-kind="spell"] .card.is-set').count());
  await page.locator('.zone[data-side="player"][data-kind="spell"][data-index="0"]').click(); await wait(150);
  console.log('same turn tray', await page.locator('#trayButtons').innerText());
  await page.locator('#endTurnBtn').click();
  await page.waitForFunction(() => {
    const b = document.querySelector('#endTurnBtn');
    return b && !b.disabled && document.querySelector('#phaseLabel').textContent === 'YOUR TURN';
  }, { timeout: 15000 });
  await wait(500);
  await page.locator('.zone[data-side="player"][data-kind="spell"][data-index="0"]').click(); await wait(200);
  console.log('next turn tray', await page.locator('#trayButtons').innerText());
  const act = page.locator('#trayButtons button', { hasText: '発動' }).first();
  console.log('activate enabled', await act.isEnabled());
  await act.click(); await wait(600);
  console.log('enemyLP after set spell activation', await page.locator('#enemyLp').innerText());
  console.log('ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})();

