  await page.locator('#stageBtn').click(); await wait(300);
  const m = await page.evaluate(() => { const el = document.querySelector('.modal'); return { sh: el.scrollHeight, ch: el.clientHeight, top: el.getBoundingClientRect().top, bottom: el.getBoundingClientRect().bottom }; });
  console.log('modal', m);
  await page.screenshot({ path: '/tmp/opencode/320-select.png' });
  console.log('ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})();
